fn clean(x: string) -> string { return string.lower(string.trim(x)) }
flow Report(raw: string) -> object {
    parts = string.split(raw, ",")
    cleaned = list.map(parts, clean)
    nonempty = list.filter(cleaned, fn(x) { x != "" })
    tags = list.unique(nonempty)
    return {tags: tags, count: len(tags), label: string.join(tags, " / ")}
}
